/*! `typst` grammar for Highlight.js 11, written for Greece (MIT, same as Greece's own code) */
(()=>{if(typeof hljs==="undefined")return;hljs.registerLanguage("typst",function(h){
const K={keyword:"let set show if else for in while break continue return import include as context not and or",literal:"none auto true false"};
const C=[h.C_LINE_COMMENT_MODE,h.C_BLOCK_COMMENT_MODE];
const S={scope:"string",begin:/"/,end:/"/,contains:[h.BACKSLASH_ESCAPE]};
const N={scope:"number",match:/\b\d+(?:\.\d+)?(?:pt|mm|cm|in|em|fr|deg|rad|%)?\b/};
const M={scope:"built_in",begin:/\$/,end:/\$/,contains:[h.BACKSLASH_ESCAPE]};
const RB={scope:"code",begin:/```/,end:/```/};
const R={scope:"code",begin:/`/,end:/`/};
const L={scope:"symbol",match:/<[\w:.-]+>/};
const F={scope:"link",match:/@[\w:.-]+/};
const CONTENT={begin:/\[/,end:/\]/,contains:[]};
const CALL={scope:"title.function",match:/[A-Za-z_][\w-]*(?:\.[A-Za-z_][\w-]*)*(?=[(\[])/};
const NAMED={scope:"attr",match:/[A-Za-z_][\w-]*(?=\s*:(?!\/))/};
const ARGS={begin:/\(/,end:/\)/,keywords:K,contains:[]};
const CODE=[...C,S,N,M,R,L,CALL,NAMED,ARGS,CONTENT];
ARGS.contains=CODE;
const HK={begin:/#(?:let|set|show|import|include|if|else|for|while|return|context)\b/,beginScope:"keyword",end:/$|(?=\])/,keywords:K,contains:CODE};
const HC={begin:[/#[A-Za-z_][\w-]*(?:\.[A-Za-z_][\w-]*)*/,/\(/],beginScope:{1:"title.function"},end:/\)/,keywords:K,contains:CODE};
const HB={scope:"title.function",match:/#[A-Za-z_][\w-]*(?:\.[A-Za-z_][\w-]*)*(?=\[)/};
const HV={scope:"variable",match:/#[A-Za-z_][\w-]*(?:\.[A-Za-z_][\w-]*)*/};
const ST={scope:"strong",begin:/\*(?=\S)/,end:/\*/,contains:[M,R]};
const EM={scope:"emphasis",begin:/(?<![\w])_(?=\S)/,end:/_(?![\w])/,contains:[M,R]};
const LI={scope:"bullet",match:/^\s*(?:[-+]|\d+\.)(?=\s)/};
const TE={scope:"bullet",match:/^\s*\/\s[^:\n]*:/};
const E={match:/\\[\\#$*_`<@\[\]=\/-]/};
const HD={scope:"section",begin:/^\s*=+(?=\s)/,end:/$/,contains:[M,R,ST,EM,L,HV]};
const MARKUP=[...C,E,HD,RB,R,M,HK,HC,HB,HV,L,F,ST,EM,LI,TE];
CONTENT.contains=MARKUP;
return{name:"Typst",aliases:["typ"],contains:MARKUP};
});})();
